create temporary view dwd_derived_scenario_${grass_region_without_quote} as
select
    if(user_id > 0, user_id, -1 * cast(crc32(device_id) as bigint)) as user_id
     ,coalesce(cast(is_ads as string), 'false') as is_ads
     ,feature_detail
     ,source1_feature_detail
     ,source2_feature_detail
     ,case when location >= 200 then 200 else location end as location
     ,case when source1_location >= 200 then 200 else source1_location end as source1_location
     ,case when source2_location >= 200 then 200 else source2_location end as source2_location
     ,exp_group_ids

     ,target_type
     ,source1_target_type
     ,source2_target_type
     ,operation
     ,operation_cnt
     ,is_back
     ,place_order_gmv
     ,window_day
     ,FILTER(coalesce(split(if(algo_tag = '', null, algo_tag), ','), array()),
             value -> value like '%DA_%'
      ) AS scenario_tags
     ,FILTER(coalesce(split(if(source1_algo_tag = '', null, source1_algo_tag), ','), array()),
             value -> value like '%DA_%'
      ) AS source1_scenario_tags
     ,FILTER(coalesce(split(if(source2_algo_tag = '', null, source2_algo_tag), ','), array()),
             value -> value like '%DA_%'
      ) AS source2_scenario_tags
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region in (${grass_region})
  and local_date = ${local_date}
  and operation in ('impression', 'click', 'ppv', 'cart', 'order', 'omni_impression', 'omni_click')
  and feature_detail not in ('bottom_bar-tab', 'phone_notifications-push_notification','chat-chat_conversation','home-home_circle','me-self_design_button',
                             'home-skinny_banner', 'home-shopee_wallet-button','product-image_card','product-variation_image-image')
  and size(filter(exp_group_ids, value -> value > 0)) > 0
;

