CREATE TEMPORARY VIEW base_table_${grass_region_without_quote} AS
SELECT
    user_id
     ,is_ads
     ,location
     ,exp_group_ids
     ,target_type
     ,scenario_tags
     ,sum(case when operation = 'impression' then operation_cnt else 0 end)          as imp_cnt
     ,sum(case when operation = 'click' then operation_cnt else 0 end)               as click_cnt
     ,sum(case when operation = 'omni_impression' then operation_cnt else 0 end)     as omni_imp_cnt
     ,sum(case when operation = 'omni_click' then operation_cnt else 0 end)          as omni_click_cnt
     ,sum(case when operation = 'cart' then operation_cnt else 0 end)                as cart_cnt
     ,sum(case when operation = 'ppv' then operation_cnt else 0 end)                                 as ppv_cnt
     ,sum(case when operation = 'ppv' and is_back is not true then operation_cnt else 0 end)         as ppv_cnt_exclude_isback
     ,sum(case when operation = 'order' then operation_cnt else 0 end)               as order_cnt
     ,sum(case when operation = 'order' then place_order_gmv else 0 end)             as gmv
     ,sum(if(operation='order' and window_day=1, operation_cnt, 0))                  as atc_same_day_order_cnt
     ,sum(if(operation='order' and window_day between 1 and 4, operation_cnt, 0))    as atc_within_3day_order_cnt
     ,sum(if(operation='order' and window_day=1, place_order_gmv, 0))                as atc_same_day_gmv
     ,sum(if(operation='order' and window_day between 1 and 4, place_order_gmv, 0))  as atc_within_3day_gmv
FROM dwd_derived_scenario_${grass_region_without_quote}
WHERE feature_detail IS NOT NULL
  and feature_detail NOT IN ('global_search-item', 'search_in_pdp-item')
  AND target_type IS NOT NULL
  AND SIZE(scenario_tags) >= 1
GROUP BY 1,2,3,4,5,6
UNION ALL
