CREATE TEMPORARY VIEW user_metric_row_${grass_region_without_quote} AS
SELECT user_id
     ,is_ads
     ,target_type
     ,location
     ,named_struct(
        'scenario_tags', scenario_tags,
        'exp_group_ids', exp_group_ids,
        'imp_cnt', COALESCE(CAST(imp_cnt AS BIGINT), 0L),
        'click_cnt', COALESCE(CAST(click_cnt AS BIGINT), 0L),
        'omni_imp_cnt', COALESCE(CAST(omni_imp_cnt AS BIGINT), 0L),
        'omni_click_cnt', COALESCE(CAST(omni_click_cnt AS BIGINT), 0L),
        'cart_cnt', COALESCE(CAST(cart_cnt AS BIGINT), 0L),
        'ppv_cnt', COALESCE(CAST(ppv_cnt AS BIGINT), 0L),
        'ppv_cnt_exclude_isback', COALESCE(CAST(ppv_cnt_exclude_isback AS BIGINT), 0L),
        'order_cnt', COALESCE(CAST(order_cnt AS DOUBLE), 0.0D),
        'gmv', COALESCE(CAST(gmv AS DOUBLE), 0.0D),
        'atc_same_day_order_cnt', COALESCE(CAST(atc_same_day_order_cnt AS DOUBLE), 0.0D),
        'atc_within_3day_order_cnt', COALESCE(CAST(atc_within_3day_order_cnt AS DOUBLE), 0.0D),
        'atc_same_day_gmv', COALESCE(CAST(atc_same_day_gmv AS DOUBLE), 0.0D),
        'atc_within_3day_gmv', COALESCE(CAST(atc_within_3day_gmv AS DOUBLE), 0.0D)
      ) AS user_data
FROM base_table_${grass_region_without_quote}
;

