CREATE TEMPORARY VIEW user_metric_${grass_region_without_quote} AS
SELECT user_id
     ,is_ads
     ,target_type
     ,location
     ,collect_list(user_data) as user_data_list
FROM user_metric_row_${grass_region_without_quote}
GROUP BY GROUPING SETS (
    (1,3,4), (1,2,3,4),
    (1,2,4), (1,4)
    )
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW mask_user_metric_${grass_region_without_quote} AS
select
    COALESCE(is_ads, '__ALL__') AS is_ads
    ,COALESCE(target_type, '__ALL__') AS target_type
    ,location
    ,scenario_exp_sum(user_id, user_data_list) as mask_user_metrics
from
    user_metric_${grass_region_without_quote}
group by 1,2,3;

